import React, { useState, useEffect } from 'react'
import Joyride from 'react-joyride'
import { useAuth } from '../contexts/AuthContext'

export default function OnboardingTour() {
    const { user } = useAuth()
    const [run, setRun] = useState(false)

    useEffect(() => {
        // Check if this is a brand new user
        const hasSeenTour = localStorage.getItem(`predictfc_tour_${user?.id}`)
        
        // If user exists AND they have never seen the tour, show it
        if (user && !hasSeenTour) {
            // Wait 1 second for the page to load, then start the tour
            const timer = setTimeout(() => {
                setRun(true)
            }, 1000)
            return () => clearTimeout(timer)
        }
    }, [user])

    const handleTourFinish = () => {
        // Save to localStorage so it never shows for this user again
        localStorage.setItem(`predictfc_tour_${user?.id}`, 'true')
        setRun(false)
    }

    // The steps for the tour
    const steps = [
        {
            target: 'body',
            content: (
                <div className="text-center">
                    <h3 className="font-bold text-lg mb-2">👋 Welcome to PredictFC!</h3>
                    <p className="text-sm">Let's take a quick tour so you know your way around.</p>
                </div>
            ),
            placement: 'center',
            disableBeacon: true,
        },
        {
            target: '.tour-feed', // We will add this class to the Feed button
            content: '📰 This is your Feed. See posts and predictions from the community.',
            placement: 'bottom',
        },
        {
            target: '.tour-matches', // We will add this class to the Matches button
            content: '⚽ View all upcoming matches and make your predictions here.',
            placement: 'bottom',
        },
        {
            target: '.tour-community', // We will add this class to the Community button
            content: '🏛️ Join or create private communities to predict with friends.',
            placement: 'bottom',
        },
        {
            target: '.tour-slip', // We will add this class to the Slip button
            content: '📋 Build a multi-match bet slip and share it with the world.',
            placement: 'bottom',
        },
        {
            target: '.tour-profile', // We will add this class to the Profile button
            content: '👤 Check your stats, points, and manage your profile here.',
            placement: 'bottom',
        },
        {
            target: 'body',
            content: (
                <div className="text-center">
                    <h3 className="font-bold text-lg mb-2">🎉 You're all set!</h3>
                    <p className="text-sm">Start predicting, earning points, and climbing the leaderboard!</p>
                </div>
            ),
            placement: 'center',
        },
    ]

    return (
        <Joyride
            steps={steps}
            run={run}
            continuous={true}
            showProgress={true}
            showSkipButton={true}
            hideCloseButton={true}
            disableOverlayClose={true}
            styles={{
                options: {
                    primaryColor: '#1a1a1a',
                    backgroundColor: '#ffffff',
                    textColor: '#1a1a1a',
                    arrowColor: '#ffffff',
                },
                buttonNext: {
                    backgroundColor: '#1a1a1a',
                    color: '#ffffff',
                    padding: '10px 24px',
                    borderRadius: '8px',
                    fontWeight: '600',
                },
                buttonBack: {
                    color: '#666666',
                    padding: '10px 16px',
                },
                buttonSkip: {
                    color: '#999999',
                },
            }}
            callback={(data) => {
                if (data.status === 'finished' || data.status === 'skipped') {
                    handleTourFinish()
                }
            }}
        />
    )
}
